def solve(values: list[float], window_size: int) -> list[float]:
    dq: deque[int] = deque()
    result: list[float] = []
    for i, v in enumerate(values):
        # Maintain monotonic decreasing deque of indices
        while dq and values[dq[-1]] <= v:
            dq.pop()
        dq.append(i)
        # Remove index that slid out of the window
