import heapq

def solve(tasks: list[list[int]]) -> int:
    # Sort by deadline so we process tasks earliest-deadline-first.
    # A task with deadline d can fill any of the d available slots 1..d.
    # If we've already filled d slots and the new task has higher impact
    # than the lowest-impact scheduled task, swap — that task is the one
    # least worth keeping given we have to drop something.
    tasks = sorted(tasks, key=lambda x: x[1])
    heap = []  # min-heap: impact scores of currently scheduled tasks
    for impact, deadline in tasks:
        if len(heap) < deadline:
            heapq.heappush(heap, impact)
        elif heap and heap[0] < impact:
            heapq.heapreplace(heap, impact)
    return sum(heap)
